UPDATE model_call_job
SET execution_status = 'OUTCOME_UNKNOWN',
    completed_at = CURRENT_TIMESTAMP,
    row_version = row_version + 1
WHERE id = #{jobId, jdbcType=OTHER}
  AND user_id = #{userId, jdbcType=OTHER}
  AND execution_status = 'RUNNING'
  AND row_version = #{expectedRowVersion, jdbcType=BIGINT}
RETURNING

UPDATE model_call_job
SET consumption_status = 'CONSUMED',
    row_version = row_version + 1
WHERE id = #{jobId, jdbcType=OTHER}
  AND user_id = #{userId, jdbcType=OTHER}
  AND execution_status = 'SUCCEEDED'
  AND consumption_status = 'NOT_READY'
  AND workflow_version = #{currentWorkflowVersion, jdbcType=BIGINT}
  AND row_version = #{expectedRowVersion, jdbcType=BIGINT}
  AND expires_at > CURRENT_TIMESTAMP
RETURNING

UPDATE model_call_job
SET consumption_status = 'STALE',
    row_version = row_version + 1
WHERE id = #{jobId, jdbcType=OTHER}
  AND user_id = #{userId, jdbcType=OTHER}
  AND execution_status = 'SUCCEEDED'
  AND consumption_status = 'NOT_READY'
  AND workflow_version < #{currentWorkflowVersion, jdbcType=BIGINT}
  AND row_version = #{expectedRowVersion, jdbcType=BIGINT}
  AND expires_at > CURRENT_TIMESTAMP
RETURNING
